    F = -2*b**2*d*g*x - b**2*f*h*x**4/32 - 2*b**2*x**3*(e*h + f*g)/27 - b**2*x**2*(d*h + e*g)/4 - 3*b**2*f*h*x**2/(32*c**2) - 4*b**2*x*(e*h + f*g)/(9*c**2) + 2*b*d*g*(a + b*asin(c*x))*sqrt(-c**2*x**2 + 1)/c + b*f*h*x**3*(a + b*asin(c*x))*sqrt(-c**2*x**2 + 1)/(8*c) + 2*b*x**2*(a + b*asin(c*x))*sqrt(-c**2*x**2 + 1)*(e*h + f*g)/(9*c) + b*x*(a + b*asin(c*x))*sqrt(-c**2*x**2 + 1)*(d*h + e*g)/(2*c) + 3*b*f*h*x*(a + b*asin(c*x))*sqrt(-c**2*x**2 + 1)/(16*c**3) + 4*b*(a + b*asin(c*x))*sqrt(-c**2*x**2 + 1)*(e*h + f*g)/(9*c**3) + d*g*x*(a + b*asin(c*x))**2 + f*h*x**4*(a + b*asin(c*x))**2/4 + x**3*(a + b*asin(c*x))**2*(e*h/3 + f*g/3) + x**2*(a + b*asin(c*x))**2*(d*h/2 + e*g/2) - (a + b*asin(c*x))**2*(d*h + e*g)/(4*c**2) - 3*f*h*(a + b*asin(c*x))**2/(32*c**4)
    assert integrate(f, x) == F


